INSERT INTO "Category" ("id","name","slug","domain","isActive","sortOrder","parentId","createdAt","updatedAt")
SELECT md5(random()::text || clock_timestamp()::text),s.name,s.slug,s.domain::"CategoryDomain",true,s.sort,p."id",NOW(),NOW()
FROM specifications s JOIN "Category" p ON p.slug=s.parent
ON CONFLICT ("slug") DO NOTHING;

