INSERT INTO "CategoryAttributeOption" ("id","attributeId","value","label","sortOrder")
SELECT md5(random()::text || clock_timestamp()::text),ca.id,val.value,val.value,val.ordinality::int*10
FROM specifications s
JOIN "Category" c ON c.slug=s.slug
JOIN "CategoryAttribute" ca ON ca."categoryId"=c.id AND ca.key=s.key
CROSS JOIN LATERAL jsonb_array_elements_text(s.options) WITH ORDINALITY AS val(value,ordinality)
ON CONFLICT ("attributeId","value") DO NOTHING;
